def monthly_returns(daily: pd.DataFrame) -> pd.DataFrame:
    """일별 단순수익률 -> 월별 복리 수익률 (월말 라벨)."""
    return (1 + daily).resample("ME").prod() - 1  # 월별 복리 누적곱 후 -1

