def tolerance(target: float, band_abs: float, band_rel: float) -> float:
    """5/25 규칙: 큰 비중은 ±band_abs, 작은 비중은 ±band_rel*목표 중 좁은 쪽."""
    return min(band_abs, band_rel * target)  # 큰 슬리브는 ±5%p, 작은 슬리브는 목표의 ±25%

